schemas.schema-1-auth.prisma:
/// Registered customer accounts with email and password credentials and
/// account status for login control.
///
/// This table is the authentication root for customer shoppers in the
/// marketplace. It stores the unique sign-in identity, credential hash, and
/// account lifecycle state used to control access to customer features.
///
/// Customer-specific session, password reset, and profile data are managed
/// in separate tables owned by other components, so this model remains
/// focused on authentication and account status only.
///
/// @namespace auth
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model mall_platform_customers {
  //----
  // COLUMNS
  //----
  /// Primary key for the customer account.
  id String @id @db.Uuid

  /// Unique email address used for customer login and account identification.
  email String

  /// Hashed password used to authenticate the customer account.
  password_hash String

  /// Current account state for login control, such as active, banned, or
  /// deleted.
  status String

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was soft-deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions mall_platform_customer_sessions[]
  passwordResets mall_platform_customer_password_resets[]
  profile mall_platform_customer_profiles?
  shippingAddresses mall_platform_shipping_addresses[]
  shoppingCart mall_platform_shopping_carts?
  wishlist mall_platform_wishlists?
  orders mall_platform_orders[]
  refundRequests mall_platform_refund_requests[]
  reviews mall_platform_reviews[]
  reviewSnapshots mall_platform_review_snapshots[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([status, created_at])
}

