  customer mall_platform_customers @relation(fields: [mall_platform_customer_id], references: [id], onDelete: Cascade, map: "mall_platform_customer_password_resets_mall_platform_c_923892ae")

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([mall_platform_customer_id, created_at], map: "mall_platform_customer_password_resets_mall_platform_c_16a8332b")
}

/// Registered seller accounts used for authentication, account lifecycle
/// control, and platform moderation. This table stores the seller's login
/// credentials and account status only; public shop presentation data,
/// approval workflows, sessions, and password resets are handled by separate
/// tables in other components.
///
/// The record is the authoritative identity for a seller actor and supports
/// login, approval visibility, rejection handling, suspension, and deletion
/// controls without duplicating profile or request history data.
///
/// @namespace auth
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model mall_platform_sellers {
  //----
  // COLUMNS
  //----
  /// Primary key for the seller account.
  id String @id @db.Uuid

  /// Unique email address used for seller sign-in.
  email String

  /// Hashed password used to authenticate the seller account.
  password_hash String

  /// Current account state for seller login and moderation control, such as
  /// pending, approved, rejected, suspended, or banned.
  status String

  /// Reason provided when the seller registration is rejected. Null unless the
  /// account is in a rejected state.
  rejection_reason String?

  /// Timestamp when the seller account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was soft-deleted. Null when the account
  /// is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions mall_platform_seller_sessions[]
  orderItems mall_platform_order_items[]
  shipments mall_platform_shipments[]
  refundRequests mall_platform_refund_requests[]
  approvalRequests mall_platform_seller_approval_requests[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([status, created_at])
}

