/**
 * Retrieves the immutable snapshot history for a seller order item.
 *
 * Validates that the seller-scoped snapshot history endpoint returns a paginated
 * list of preserved order-item snapshots and that the returned records remain
 * immutable audit entries. The test focuses on response structure, snapshot
 * chronology, and nested order-item context because the available test surface
 * does not expose separate setup APIs for constructing a persisted order item.
 *
 * 1. Authenticate a fresh seller account through the seller join endpoint.
 * 2. Request snapshot history for a randomly generated order and order-item id
 *    using a valid pagination body and default ordering.
 * 3. Assert the paginated response shape and verify snapshot chronology and
 *    preserved nested summaries when records are returned.
 */
export async function test_api_order_item_snapshot_history_retrieval(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IMallPlatformSeller.IJoin,
  });
  typia.assert(seller);
  const response =
    await api.functional.mallPlatform.seller.orders.orderItems.snapshots.index(
      sellerConnection,
      {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        orderItemId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          page: 1,
          limit: 10,
        } satisfies IMallPlatformOrderItemSnapshot.IRequest,
      },
    );
  typia.assert(response);
  TestValidator.predicate(
    "snapshot history page should be non-negative",
    response.pagination.current >= 0 &&
      response.pagination.limit >= 0 &&
      response.pagination.records >= 0 &&
      response.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "snapshot history page should respect requested size",
    response.data.length <= response.pagination.limit,
  );
  for (let index = 1; index < response.data.length; index++) {
    TestValidator.predicate(
      "snapshots should be ordered newest-first by snapshotAt",
      response.data[index - 1].snapshotAt >= response.data[index].snapshotAt,
    );
  }
  for (const snapshot of response.data) {
    typia.assert(snapshot);
    TestValidator.predicate(
      "snapshot should preserve positive quantities and pricing",
      snapshot.quantity > 0 &&
        snapshot.unitPrice >= 0 &&
        snapshot.lineTotal >= 0,
    );
    TestValidator.equals(
      "snapshot order item should stay attached to the parent order",
      snapshot.orderItem.order.id,
      response.data[0]?.orderItem.order.id ?? snapshot.orderItem.order.id,
    );
    TestValidator.predicate(
      "snapshot should carry preserved product and seller references",
      snapshot.orderItem.productVariant.product.id.length > 0 &&
        snapshot.orderItem.seller.id.length > 0 &&
        snapshot.orderItem.productVariant.skuCode.length > 0,
    );
  }
}

