  const repeatedResponse =
    await api.functional.mallPlatform.customer.shipments.index(
      customerConnection,
      { body: filteredRequest },
    );
  typia.assert(repeatedResponse);
  const nextPageResponse =
    await api.functional.mallPlatform.customer.shipments.index(
      customerConnection,
      {
        body: {
          ...filteredRequest,
          page: 2,
        } satisfies IMallPlatformShipment.IRequest,
      },
