export async function test_api_shipment_update_tracking_and_status(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Verify seller shipment tracking and status updates.
   *
   * This test validates the seller-owned shipment update flow for tracking
   * header corrections and lifecycle transitions.
   *
   * 1. Authenticate a seller session through the seller join utility.
   * 2. Update a shipment's carrier and tracking details in the seller scope.
   * 3. Transition the shipment status from preparing to shipped and delivered.
   * 4. Confirm that ownership, order linkage, and timestamp behavior remain
   *    consistent across updates.
   */
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IMallPlatformSeller.IJoin,
  });
  typia.assert(seller);
  const shipmentId = typia.random<string & tags.Format<"uuid">>();
  const carrierName = RandomGenerator.name();
  const trackingNumber = RandomGenerator.alphaNumeric(18);
  const trackingUrl =
    `https://tracking.example.com/${trackingNumber}` as string &
      tags.Format<"url">;
  const preparing = await api.functional.mallPlatform.seller.shipments.update(
    sellerConnection,
    {
      shipmentId,
      body: {
        carrierName,
        trackingNumber,
        trackingUrl,
        status: "preparing",
      } satisfies IMallPlatformShipment.IUpdate,
    },
  );
  typia.assert(preparing);
  TestValidator.equals(
    "shipment id should remain stable",
    preparing.id,
    shipmentId,
  );
  TestValidator.equals(
    "shipment carrier name should match update",
    preparing.carrierName,
    carrierName,
  );
  TestValidator.equals(
    "shipment tracking number should match update",
    preparing.trackingNumber,
    trackingNumber,
  );
  TestValidator.equals(
    "shipment tracking url should match update",
    preparing.trackingUrl,
    trackingUrl,
  );
  TestValidator.equals(
    "shipment seller should remain the same",
    preparing.seller.id,
    seller.id,
  );
  TestValidator.equals(
    "shipment seller email should remain the same",
    preparing.seller.email,
    seller.email,
  );
  TestValidator.equals(
    "shipment status should remain preparing",
    preparing.status,
    "preparing",
  );
  TestValidator.equals(
    "shipment shippedAt should remain null while preparing",
    preparing.shippedAt,
    null,
  );
  TestValidator.equals(
    "shipment deliveredAt should remain null while preparing",
    preparing.deliveredAt,
    null,
  );
  const shipped = await api.functional.mallPlatform.seller.shipments.update(
    sellerConnection,
    {
      shipmentId,
      body: {
        carrierName,
        trackingNumber,
        trackingUrl,
        status: "shipped",
      } satisfies IMallPlatformShipment.IUpdate,
    },
  );
  typia.assert(shipped);
  TestValidator.equals(
    "shipment id should remain stable after shipped transition",
    shipped.id,
    shipmentId,
  );
  TestValidator.equals(
    "shipment carrier name should persist after shipped transition",
    shipped.carrierName,
    carrierName,
  );
  TestValidator.equals(
    "shipment tracking number should persist after shipped transition",
    shipped.trackingNumber,
    trackingNumber,
  );
  TestValidator.equals(
    "shipment tracking url should persist after shipped transition",
    shipped.trackingUrl,
    trackingUrl,
  );
  TestValidator.equals(
    "shipment seller should remain stable after shipped transition",
    shipped.seller.id,
    seller.id,
  );
  TestValidator.equals(
    "shipment order should remain stable after shipped transition",
    shipped.order.id,
    preparing.order.id,
  );
  TestValidator.equals(
    "shipment status should be shipped",
    shipped.status,
    "shipped",
  );
  TestValidator.predicate(
    "shipment shippedAt should be populated when shipped",
    shipped.shippedAt !== null,
  );
  TestValidator.equals(
    "shipment deliveredAt should remain null when shipped",
    shipped.deliveredAt,
    null,
  );
  const delivered = await api.functional.mallPlatform.seller.shipments.update(
    sellerConnection,
    {
      shipmentId,
      body: {
        carrierName,
        trackingNumber,
        trackingUrl,
        status: "delivered",
      } satisfies IMallPlatformShipment.IUpdate,
    },
  );
  typia.assert(delivered);
  TestValidator.equals(
    "shipment id should remain stable after delivered transition",
    delivered.id,
    shipmentId,
  );
  TestValidator.equals(
    "shipment carrier name should persist after delivered transition",
    delivered.carrierName,
    carrierName,
  );
  TestValidator.equals(
    "shipment tracking number should persist after delivered transition",
    delivered.trackingNumber,
    trackingNumber,
  );
  TestValidator.equals(
    "shipment tracking url should persist after delivered transition",
    delivered.trackingUrl,
    trackingUrl,
  );
  TestValidator.equals(
    "shipment seller should remain stable after delivered transition",
    delivered.seller.id,
    seller.id,
  );
  TestValidator.equals(
    "shipment order should remain stable after delivered transition",
    delivered.order.id,
    preparing.order.id,
  );
  TestValidator.equals(
    "shipment status should be delivered",
    delivered.status,
    "delivered",
  );
