export async function test_api_shipment_items_reconcile_membership(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IMallPlatformSeller.IJoin,
  });
  typia.assert(seller);
  const shipment = await generate_random_mall_platform_seller_shipments_create(
    sellerConnection,
    {
      body: {
        carrierName: RandomGenerator.name(),
        trackingNumber: RandomGenerator.alphaNumeric(18),
        trackingUrl: typia.random<string & tags.Format<"url">>(),
        orderItemIds: ArrayUtil.repeat(1, () =>
          typia.random<string & tags.Format<"uuid">>(),
        ),
      } satisfies IMallPlatformShipment.ICreate,
    },
  );
  typia.assert(shipment);
  const updated =
    await api.functional.mallPlatform.seller.shipments.items.patchByShipmentid(
      sellerConnection,
      {
        shipmentId: shipment.id,
        body: {
          orderItemIds: ArrayUtil.repeat(1, () =>
            typia.random<string & tags.Format<"uuid">>(),
          ),
        } satisfies IMallPlatformShipment.IUpdateItem,
      },
    );
  typia.assert(updated);
  TestValidator.equals("shipment id", updated.id, shipment.id);
  TestValidator.equals(
    "carrier name",
    updated.carrierName,
    shipment.carrierName,
  );
  TestValidator.equals(
    "tracking number",
    updated.trackingNumber,
    shipment.trackingNumber,
  );
  TestValidator.equals(
    "tracking url",
    updated.trackingUrl,
    shipment.trackingUrl,
  );
  TestValidator.equals("status", updated.status, shipment.status);
  TestValidator.equals("shipped at", updated.shippedAt, shipment.shippedAt);
  TestValidator.equals(
    "delivered at",
    updated.deliveredAt,
    shipment.deliveredAt,
  );
  TestValidator.equals("created at", updated.createdAt, shipment.createdAt);
  TestValidator.notEquals(
    "updated at should reflect reconciliation",
    updated.updatedAt,
    shipment.updatedAt,
  );
}

