export async function test_api_cancellation_request_create_paid_unshipped_item(
  connection: api.IConnection,
): Promise<void> {
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IMallPlatformCustomer.IJoin,
  });
  typia.assert(customer);
  const order = await api.functional.mallPlatform.customer.orders.at(
    customerConnection,
    {
      orderId: typia.random<string & tags.Format<"uuid">>(),
    },
  );
  typia.assert(order);
  const targetItem = order.orderItems.find((item) => item.status === "paid");
  TestValidator.predicate(
    "order contains at least one paid and unshipped order item",
    targetItem !== undefined,
  );
  if (targetItem === undefined) return;
  const siblingItems = order.orderItems.filter(
    (item) => item.id !== targetItem.id,
  );
  const siblingSnapshots = siblingItems.map((item) => ({
    id: item.id,
    status: item.status,
    quantity: item.quantity,
    productVariantId: item.productVariant.id,
    sellerId: item.seller.id,
  }));
  const reason = RandomGenerator.paragraph({ sentences: 2 });
  const request =
    await api.functional.mallPlatform.customer.orderItems.cancellationRequests.patchByOrderitemid(
      customerConnection,
      {
        orderItemId: targetItem.id,
        body: {
          reason,
        } satisfies IMallPlatformCancellationRequest.ICreate,
      },
    );
  typia.assert(request);
  TestValidator.equals(
    "cancellation request targets the correct order item",
    request.orderItem.id,
    targetItem.id,
  );
  TestValidator.equals(
    "cancellation reason is preserved",
    request.reason,
    reason,
  );
  TestValidator.equals(
    "cancellation request starts in pending state",
    request.status,
    "pending",
  );
  TestValidator.equals(
    "cancellation request has no reviewer yet",
    request.reviewer,
    null,
  );
  TestValidator.equals(
    "cancellation request has no review result yet",
    request.reviewResult,
    null,
  );
  TestValidator.equals(
    "cancellation request has no reviewer note yet",
    request.reviewerNote,
    null,
  );
  TestValidator.equals(
    "the order item remains paid when the request is created",
    request.orderItem.status,
    "paid",
  );
  TestValidator.equals(
    "the submitted request does not alter sibling order items",
    siblingItems.map((item) => ({
      id: item.id,
      status: item.status,
      quantity: item.quantity,
      productVariantId: item.productVariant.id,
      sellerId: item.seller.id,
    })),
    siblingSnapshots,
  );
}

