  );
  TestValidator.equals(
    "original reviewResult is preserved",
    firstRequest.reviewResult,
    preservedReviewResult,
  );
  TestValidator.equals(
    "original reviewerNote is preserved",
    firstRequest.reviewerNote,
    preservedReviewerNote,
  );
  TestValidator.equals(
