  const response =
    await api.functional.mallPlatform.seller.orderItems.cancellationRequests.update(
      sellerConnection,
      {
        orderItemId,
        cancellationRequestId,
        body: {
          decision: "approve",
          reviewerNote,
        } satisfies IMallPlatformCancellationRequest.IUpdate,
      },
    );
  typia.assert(response);
  TestValidator.equals(
    "cancellation request is approved",
    response.status,
    "approved",
  );
  TestValidator.equals(
    "cancellation request is reviewed",
    response.reviewedAt !== null,
