  );
  TestValidator.equals(
    "response is tied to the requested order item",
    response.orderItem.id,
    orderItemId,
  );
  TestValidator.equals(
    "order item is cancelled",
    response.orderItem.status,
    "cancelled",
  );
  TestValidator.equals(
    "response is tied to the requested cancellation request",
    response.id,
    cancellationRequestId,
  );
  TestValidator.equals(
    "reviewer is the seller",
    response.reviewer !== null,
    true,
  );
  if (response.reviewer !== null) {
    TestValidator.equals(
      "reviewer email matches seller",
      response.reviewer.email,
      seller.email,
    );
  }
}

