    await api.functional.mallPlatform.customer.reviews.snapshots.at(
      customerConnection,
      {
        reviewId,
        snapshotId,
      },
    );
  typia.assert(snapshot);
  TestValidator.equals("snapshot id matches request", snapshot.id, snapshotId);
  TestValidator.equals(
    "snapshot parent review matches request",
    snapshot.mall_platform_review_id,
    reviewId,
  );
  TestValidator.equals(
    "snapshot owner matches authenticated customer",
    snapshot.mall_platform_customer_id,
    joined.id,
  );
  TestValidator.predicate(
    "snapshot action is present",
    snapshot.snapshot_action.length > 0,
