      : {}),
    ...(props.body.expiredAtFrom !== undefined ||
    props.body.expiredAtTo !== undefined
      ? {
          expired_at: {
            ...(props.body.expiredAtFrom !== undefined
              ? { gte: new globalThis.Date(props.body.expiredAtFrom) }
