   */
  @TypedRoute.Get(":orderItemId")
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("orderId")
    orderId: string & tags.Format<"uuid">,
    @TypedParam("orderItemId")
    orderItemId: string & tags.Format<"uuid">,
  ): Promise<IMallPlatformOrderItem> {
    try {
      return await getMallPlatformCustomerOrdersOrderIdOrderItemsOrderItemId({
        customer,
        orderId,
        orderItemId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

