@Controller("/mallPlatform/seller/approvalRequests/resubmissions")
export class MallplatformSellerApprovalrequestsResubmissionsController {
  /**
   * Submit a new administrator approval request for a customer or seller account.
   *
   * This endpoint creates a fresh governance request when an existing user wants to be considered for administrator access again. The submitted request stores the applicant’s reason for seeking elevated access and begins in a pending state so that super administrators can review it later.
   *
   * A resubmission must not alter any previously approved or rejected administrator request. If the applicant is not eligible, the reason is missing, or the system cannot create a new request record, the operation must fail without changing existing governance history.
   *
   * @param connection
   * @param body The applicant identity and reason used to create a new administrator approval request submission.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Create a new row in mall_platform_administrator_approval_requests with a pending status and the applicant-provided reason. Validate that the request is being made by an existing customer or seller account permitted to seek administrator access, and reject attempts from unavailable account states. If the domain model distinguishes applicant identity fields, map them from the create DTO and do not derive them from any previous completed request.
   *
   * Before insertion, ensure there is no conflicting pending administrator approval request for the same applicant if the business rules prohibit duplicates. Never update a completed request; resubmission must always create a new record to preserve the approval/rejection history. Return the created request after persistence, including its current status and any review metadata that exists at creation time.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @SellerAuth()
    seller: SellerPayload,
    @TypedBody()
    body: IMallPlatformAdministratorApprovalRequest.ICreate,
  ): Promise<IMallPlatformAdministratorApprovalRequest> {
    try {
      return await postMallPlatformSellerApprovalRequestsResubmissions({
        seller,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}
